const products=[{id:'macbook-air-m1',brand:'Apple',name:'MacBook Air M1',chip:'Apple M1',ram:'8 GB',storage:'256 GB SSD',screen:'13.3-inch Retina',price:34999,tag:'THE EVERYDAY FAVOURITE',color:'purple',desc:'Light enough to go everywhere. Capable enough for your everyday ideas. A versatile MacBook for study, work and creative exploration.'},{id:'macbook-pro-m1',brand:'Apple',name:'MacBook Pro M1',chip:'Apple M1',ram:'8 GB',storage:'512 GB SSD',screen:'13.3-inch Retina',price:44999,tag:'MORE ROOM TO CREATE',color:'green',desc:'A capable creative companion with room for your projects. Explore the MacBook Pro for productive days and ideas that keep growing.'},{id:'dell-latitude-5420',brand:'Dell',name:'Dell Latitude 5420',chip:'Intel Core i5 (11th Gen)',ram:'16 GB',storage:'512 GB SSD',screen:'14-inch Full HD',price:26999,tag:'READY FOR THE WORKDAY',color:'orange',desc:'A practical business laptop for your daily workflow. Roomy memory and solid-state storage for documents, browser tabs and everyday work.'},{id:'macbook-air-m2',brand:'Apple',name:'MacBook Air M2',chip:'Apple M2',ram:'8 GB',storage:'256 GB SSD',screen:'13.6-inch Liquid Retina',price:52999,tag:'A LITTLE MORE POSSIBILITY',color:'blue',desc:'A fresh design with a spacious display and Apple silicon. A portable companion for the things you love to make.'},{id:'hp-elitebook-840',brand:'HP',name:'HP EliteBook 840 G8',chip:'Intel Core i5 (11th Gen)',ram:'16 GB',storage:'256 GB SSD',screen:'14-inch Full HD',price:28999,tag:'WORK FROM ANYWHERE',color:'purple',desc:'A thoughtfully built business notebook for meetings, presentations and getting things done wherever the day takes you.'},{id:'lenovo-thinkpad-t14',brand:'Lenovo',name:'Lenovo ThinkPad T14',chip:'Intel Core i5 (10th Gen)',ram:'16 GB',storage:'512 GB SSD',screen:'14-inch Full HD',price:27999,tag:'YOUR DAILY WORKHORSE',color:'green',desc:'A familiar business favourite with a practical design. Built around productive days and a comfortable typing experience.'}];
const galleries={
 'macbook-air-m1':{file:'images/products/atlas-air.png',cols:2,rows:2,labels:['Front view','Closed lid','Keyboard view','Left side']},
 'macbook-pro-m1':{file:'images/products/atlas-pro.png',cols:2,rows:2,labels:['Front view','Closed lid','Keyboard view','Left side']},
 'macbook-air-m2':{file:'images/products/atlas-m2.png',cols:2,rows:1,labels:['Front view','Keyboard view']},
 'dell-latitude-5420':{file:'images/products/atlas-dell.png',cols:2,rows:2,labels:['Left angle','Right angle','Front view','Rear view']},
 'hp-elitebook-840':{file:'images/products/atlas-hp.png',cols:2,rows:2,labels:['Front view','Keyboard detail','Rear angle','Left side']},
 'lenovo-thinkpad-t14':{file:'images/products/atlas-lenovo.png',cols:2,rows:2,labels:['Front view','Left side','Rear angle','Front angle']}
};
const photoRegions={
 'macbook-air-m1':[[0,100,670,520],[670,100,584,520],[0,640,690,560],[690,627,564,573]],
 'dell-latitude-5420':[[0,0,640,700],[640,0,614,700],[0,710,650,544],[650,710,604,544]],
 'hp-elitebook-840':[[0,0,650,627],[650,0,604,627],[0,627,650,627],[650,627,604,627]]
};
function photoMarkup(p,index=0,extra=''){
 const g=galleries[p.id],w=g.rows===1?1774:1254,h=g.rows===1?887:1254;
 const r=photoRegions[p.id]?.[index]||[index%g.cols*w/g.cols,Math.floor(index/g.cols)*h/g.rows,w/g.cols,h/g.rows];
 const [x,y,rw,rh]=r,ratio=rw/rh;
 return `<span class="photo-sprite ${extra}"><span class="photo-crop" style="width:${Math.min(100,ratio*100)}%;aspect-ratio:${rw}/${rh}"><img src="${g.file}" alt="${p.name} — ${g.labels[index]}" width="${w}" height="${h}" style="width:${w/rw*100}%;height:${h/rh*100}%;left:${-x/rw*100}%;top:${-y/rh*100}%" draggable="false"></span></span>`
}
document.querySelector('#heroLaptop').innerHTML=photoMarkup(products[0],0,'hero-photo');
document.querySelector('#sellPhoto').innerHTML=photoMarkup(products[1],2);
const money=n=>'₹'+n.toLocaleString('en-IN');
let filter='All',selected=null,photoIndex=0,zoomed=false;
const grid=document.querySelector('#products');
function render(){const query=document.querySelector('#search').value.toLowerCase();let list=products.filter(p=>(filter==='All'||(filter==='Windows'?p.brand!=='Apple':p.brand===filter))&&(p.name+' '+p.chip+' '+p.ram).toLowerCase().includes(query));const sort=document.querySelector('#sort').value;if(sort!=='featured')list.sort((a,b)=>sort==='low'?a.price-b.price:b.price-a.price);grid.innerHTML=list.length?list.map(p=>`<article class="product-card"><button class="product-visual" data-open="${p.id}" aria-label="View ${p.name}"><span class="badge">${p.tag}</span>${photoMarkup(p)}<span class="view360">↗ View photo gallery</span></button><div class="product-info"><small>${p.brand==='Apple'?'APPLE MACBOOK':'WINDOWS LAPTOP'}</small><h3><a href="#product/${p.id}">${p.name}</a></h3><div class="specs">${p.ram} memory <span>·</span> ${p.storage}</div><div class="product-bottom"><div class="price"><small>ILLUSTRATIVE PRICE</small>${money(p.price)}</div><button class="round" data-open="${p.id}" aria-label="View ${p.name} details">↗</button></div></div></article>`).join(''):'<div class="empty">No laptops match your search. Try a different model or brand.</div>';grid.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>location.hash='product/'+b.dataset.open)}
render();document.querySelectorAll('[data-brand]').forEach(b=>b.onclick=()=>{filter=b.dataset.brand;document.querySelectorAll('[data-brand]').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelector('#search').oninput=render;document.querySelector('#sort').onchange=render;
const pd=document.querySelector('#productDialog');
function openProduct(id){selected=products.find(p=>p.id===id);if(!selected)return;const p=selected;photoIndex=0;zoomed=false;document.querySelector('#productContent').innerHTML=`<div class="detail-grid"><div><div class="photo-gallery"><div class="detail-view" id="detailView" tabindex="0" aria-label="${p.name} photo gallery. Use left and right arrow keys to change angles."></div><div class="gallery-topline"><span id="photoCaption" aria-live="polite"></span><button id="zoomPhoto" type="button" aria-pressed="false">＋ Zoom</button></div><div class="photo-thumbnails" id="photoThumbnails" role="group" aria-label="Choose product photo angle"></div><div class="gallery-nav"><button id="previousPhoto" type="button" aria-label="Previous product photo">←</button><span id="photoCounter" aria-live="polite"></span><button id="nextPhoto" type="button" aria-label="Next product photo">→</button></div><p class="viewer-help">Reference photos with backgrounds removed. Confirm the exact unit’s condition in-store.</p></div></div><div class="detail-text"><div class="eyebrow">${p.brand.toUpperCase()} / PRE-OWNED</div><h2>${p.name}</h2><div class="price">${money(p.price)} <small>ILLUSTRATIVE PRICE · CONFIRM IN-STORE</small></div><p>${p.desc}</p><table class="detail-specs"><tr><td>Processor</td><td>${p.chip}</td></tr><tr><td>Memory</td><td>${p.ram}</td></tr><tr><td>Storage</td><td>${p.storage}</td></tr><tr><td>Display</td><td>${p.screen}</td></tr><tr><td>Condition & battery</td><td>Confirm for selected unit</td></tr><tr><td>Warranty & availability</td><td>Confirm in-store</td></tr></table><button class="button dark" id="shortlist">Save to my shortlist ↗</button><a class="button" href="#visit" id="productVisit">Plan a store visit →</a><p class="detail-note">This is a sample configuration. Inspect the actual laptop and confirm its specifications, price and warranty before purchase.</p></div></div>`;setupGallery();document.querySelector('#shortlist').onclick=()=>{let saved=[];try{saved=JSON.parse(localStorage.getItem('amc-shortlist')||'[]');if(!Array.isArray(saved))saved=[];if(!saved.includes(p.id))saved.push(p.id);localStorage.setItem('amc-shortlist',JSON.stringify(saved));toast('Saved on this device. Download your shortlist below.');}catch{toast('Download your shortlist to keep a copy.')}download(`${p.name}\nProcessor: ${p.chip}\nMemory: ${p.ram}\nStorage: ${p.storage}\nDisplay: ${p.screen}\nIllustrative price: ${money(p.price)}\n\nConfirm exact specifications, condition, battery, warranty and availability in-store.\nAMC Infotech Solution — Sanjay Place, Agra`,'AMC-'+p.id+'-shortlist.txt')};document.querySelector('#productVisit').onclick=()=>pd.close();if(!pd.open)pd.showModal()}
function setupGallery(){
 const g=galleries[selected.id];
 document.querySelector('#photoThumbnails').innerHTML=g.labels.map((label,i)=>`<button type="button" class="photo-thumb" data-photo="${i}" aria-label="Show ${label.toLowerCase()}" aria-pressed="${i===0}">${photoMarkup(selected,i)}<span>${label}</span></button>`).join('');
 document.querySelectorAll('[data-photo]').forEach(button=>button.onclick=()=>showPhoto(+button.dataset.photo));
 document.querySelector('#previousPhoto').onclick=()=>showPhoto(photoIndex-1);
 document.querySelector('#nextPhoto').onclick=()=>showPhoto(photoIndex+1);
 const area=document.querySelector('#detailView');
 area.onkeydown=e=>{if(e.key==='ArrowRight'){e.preventDefault();showPhoto(photoIndex+1)}if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(photoIndex-1)}};
 let pointerStart=null;
 area.onpointerdown=e=>{pointerStart={x:e.clientX,y:e.clientY};area.setPointerCapture(e.pointerId)};
 area.onpointerup=e=>{if(!pointerStart)return;const dx=e.clientX-pointerStart.x,dy=e.clientY-pointerStart.y;pointerStart=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))showPhoto(photoIndex+(dx<0?1:-1))};
 area.onpointercancel=()=>pointerStart=null;
 document.querySelector('#zoomPhoto').onclick=()=>{zoomed=!zoomed;area.classList.toggle('zoomed',zoomed);document.querySelector('#zoomPhoto').textContent=zoomed?'− Zoom out':'＋ Zoom';document.querySelector('#zoomPhoto').setAttribute('aria-pressed',String(zoomed))};
 showPhoto(0);
}
function showPhoto(index){const g=galleries[selected.id];photoIndex=(index+g.labels.length)%g.labels.length;zoomed=false;const area=document.querySelector('#detailView');area.classList.remove('zoomed');area.innerHTML=photoMarkup(selected,photoIndex);document.querySelector('#photoCaption').textContent=g.labels[photoIndex];document.querySelector('#photoCounter').textContent=`${photoIndex+1} / ${g.labels.length} angles`;document.querySelector('#zoomPhoto').textContent='＋ Zoom';document.querySelector('#zoomPhoto').setAttribute('aria-pressed','false');document.querySelectorAll('[data-photo]').forEach(button=>{const active=+button.dataset.photo===photoIndex;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))})}
function route(){if(location.hash.startsWith('#product/'))openProduct(location.hash.split('/')[1]);else if(pd.open)pd.close()}window.addEventListener('hashchange',route);route();
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>{b.closest('dialog').close();if(b.closest('dialog')===pd&&location.hash.startsWith('#product/')){history.replaceState(null,'','#collection')}});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));pd.addEventListener('cancel',()=>history.replaceState(null,'','#collection'));
document.querySelector('#sellButton').onclick=()=>document.querySelector('#sellDialog').showModal();
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelector('#sellForm').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);download('AMC Infotech Solution — Laptop valuation checklist\n\n'+Array.from(data).map(([k,v])=>k.toUpperCase()+': '+v).join('\n')+'\n\nBefore visiting:\n- Back up your personal files.\n- Bring the charger and proof of ownership.\n- Check battery health and note repairs.\n- Do not share account passwords.\n\nNo valuation or booking has been made online. A final offer requires inspection and store confirmation.\nLocation: Sanjay Place, Agra. Confirm the exact shop address before travelling.','AMC-Laptop-Valuation-Checklist.txt');e.target.querySelector('.form-result').textContent='Your checklist is ready. Bring it with your laptop for an inspection. Nothing has been sent to the store.'};
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3500)}document.querySelector('.menu').onclick=()=>document.querySelector('nav').classList.toggle('open');document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>document.querySelector('nav').classList.remove('open'));document.querySelector('#year').textContent=new Date().getFullYear();
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&innerWidth>850){const hero=document.querySelector('#heroLaptop');let queued=false;function animate(){queued=false;const first=document.querySelector('.product-visual');if(!first)return;const stage=document.querySelector('.hero-stage').getBoundingClientRect();const target=first.getBoundingClientRect();const progress=Math.max(0,Math.min(1,scrollY/Math.max(1,first.getBoundingClientRect().top+scrollY-innerHeight*.62)));const ease=progress*progress*(3-2*progress);const dx=target.left+target.width/2-(stage.left+stage.width/2);const dy=target.top+target.height/2-(stage.top+12+145);hero.style.transform=`translateX(-50%) translate(${dx*ease}px,${dy*ease}px) scale(${1-ease*.38}) rotate(${-6+ease*6}deg)`;hero.style.opacity=progress>.98?'0':'1';first.querySelector('.photo-sprite').style.opacity=progress>.98?'1':String(1-ease);};window.addEventListener('scroll',()=>{if(!queued){requestAnimationFrame(animate);queued=true}},{passive:true});animate()}
